Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=(), event=Authored(todo='foldkept', at=datetime(2026, 11, 16, 20, 47, 48, 729152), actor='bmabsout', kind='suzateryTodo', created=datetime(2026, 11, 10, 0, 0, 0), body="The lines' fold is kept across restarts: a derived cache on the box, outside git, so a new process reads only the objects written since. Laws: (1) the cache is keyed by content, the store's heads and the version of the code that folds, so a checkout of another commit reads the same as a cold fold; (2) it is keyed by which keys are held, and a destroyed key invalidates what it opened; (3) it holds no opened words in the clear, or it is a holder an erasure empties.", spec=Flat(value=0.3), rationale=('Every process opens the whole store again, and every ask waits on that fold.',), category='', waiting_on='', detail='', source=None, subtodos=(), notes=(), note=''))